template <int N>
struct Factorial {
    // Compile-time recursion via instantiation depth
    static constexpr long value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    // Base case stops instantiation, preventing stack overflow/bloat
    static constexpr long value = 1;
};

// Example of type traits: conditional specialization
template <typename T, typename U>
struct MaxSize {
    static constexpr bool T_is_larger = (sizeof(T) > sizeof(U));
    using Type = std::conditional_t<T_is_larger, T, U>;
};

// Usage: MaxSize<int, short>::Type
// Compiler calculates size differences and selects Type at compile time.
